  input  [ 1:0] debug_resp_bits_resp,
  input  [31:0] debug_resp_bits_data,

  output [31:0] exit
);

     assign debug_req_valid = 0;
     assign debug_resp_ready = 0;
     assign exit = 0;

endmodule
